// "Hoy" es el día en la zona del negocio, no en UTC: a las 8:00 de Madrid todavía
// son las 6:00 en UTC, y un día calculado en UTC se come o se inventa las citas
// de la primera y la última hora.
const c = $json;
const tz = c.tenant_timezone || 'Europe/Madrid';
const ahora = DateTime.now().setZone(tz);
return [{ json: { ...c, tz,
  desde: ahora.startOf('day').toUTC().toISO(),
  hasta: ahora.endOf('day').toUTC().toISO(),
  ahora: ahora.toUTC().toISO(),
} }];

// Un resumen POR EMPLEADO, no uno del negocio: en una gestoría cada uno tiene su
// agenda, y a Juan no le sirven las citas de Arturo.
const h = $('Code · Hoy').first().json;
const tz = h.tz;

// Si una consulta falla, esto tiene que fallar A LA VISTA. Un resumen construido
// sobre una lista vacía por un 403 diría "no tienes nada hoy" a quien tiene seis
// citas, que es peor que no mandar nada.
const lista = (nombre) => {
  const r = $(nombre).first().json || {};
  const code = r.statusCode || 0;
  if (code < 200 || code >= 300) {
    const msg = (r.body && r.body.errors && r.body.errors[0] && r.body.errors[0].message) || code;
    throw new Error(`${nombre}: Directus devolvió ${code} (${msg})`);
  }
  return (r.body && r.body.data) || [];
};
const empleados = lista('HTTP · Empleados');
const citas = lista('HTTP · Citas de hoy');
const tareas = lista('HTTP · Tareas pendientes');

const idDe = (x) => (x && typeof x === 'object') ? x.id : x;
const ahora = DateTime.fromISO(h.ahora);
const finHoy = DateTime.fromISO(h.hasta);

const salida = [];
const omitidos = [];
for (const e of empleados) {
  const suyos = new Set((e.resources || []).map(idDe).filter(Boolean));
  // Solo la cita que ATIENDE (recurso primary). Un 'participant' acompaña, no la lleva.
  const susCitas = citas.filter((a) => (a.recursos || []).some((r) =>
    suyos.has(idDe(r.resource_id)) && (r.role || 'primary') === 'primary'));
  const primera = susCitas.map((a) => a.start_at).sort()[0] || null;

  const suyas = tareas.filter((t) => t.assignee_id === e.id);
  const vencidas = suyas.filter((t) => t.due_at && DateTime.fromISO(t.due_at) < ahora).length;
  const vencenHoy = suyas.filter((t) => t.due_at
    && DateTime.fromISO(t.due_at) >= ahora && DateTime.fromISO(t.due_at) <= finHoy).length;

  const telefono = e.phone_normalized || e.phone || '';
  const nombre = e.first_name || 'equipo';
  if (!telefono) { omitidos.push({ empleado: nombre, motivo: 'sin_telefono' }); continue; }
  // Solo los días con algo: un "hoy tienes 0 citas" cada mañana enseña a no leerlo.
  // Tareas pendientes sin plazo NO cuentan por sí solas: estarían ahí todos los días.
  if (!susCitas.length && !vencenHoy && !vencidas) {
    omitidos.push({ empleado: nombre, motivo: 'nada_hoy' }); continue;
  }
  salida.push({ json: {
    telefono,
    plantilla: 'aegora_resumen_diario',
    parametros: JSON.stringify([
      nombre,
      String(susCitas.length),
      primera ? DateTime.fromISO(primera).setZone(tz).toFormat('HH:mm') : 'ninguna',
      String(suyas.length),
      String(vencidas),
    ]),
    contact_id: '',
    _empleado: nombre,
  } });
}

if (!salida.length) {
  return [{ json: { _nadie: true, empleados_con_aviso: empleados.length, omitidos } }];
}
salida[0].json._omitidos = omitidos;
return salida;

// Una línea que diga qué ha pasado hoy: a quién se le mandó, a quién no y por qué.
// Es lo que se mira cuando alguien dice "hoy no me ha llegado el resumen".
const items = $input.all().map((i) => i.json);
if (items.length === 1 && items[0]._nadie) {
  return [{ json: { enviados: 0, fallidos: [], omitidos: items[0].omitidos } }];
}
let omitidos = [];
try { omitidos = $('Code · Resúmenes').first().json._omitidos || []; } catch (e) { omitidos = []; }
return [{ json: {
  enviados: items.filter((x) => x.enviado).length,
  fallidos: items.filter((x) => !x.enviado).map((x) => x.error || x.motivo || 'desconocido'),
  omitidos,
} }];
